 describe('AccountSummary', () => {
@@ -35,4 +49,19 @@ describe('AccountSummary', () => {
     expect(summaryText).not.toMatch(/usually \d+–\d+ a week/);
     expect(summaryText).toContain('Not enough history yet (2 of 6 weeks needed)');
